# ------------------------------------------------------------------ text
MARKS = re.compile("[\u064B-\u065F\u0670\u0640\u06D6-\u06ED]")
ZW = "\u200c"
PER = "\u0600-\u06FF"


def strip_marks(s):
    return MARKS.sub("", (s or "").replace("\u06C0", "\u0647"))


def norm(s):
    return strip_marks(s).replace(ZW, "").replace("ي", "ی").replace("ك", "ک")


def fix_persian(s):
    """Standard Persian typography: ی/ک, نیم‌فاصله, punctuation, digits."""
    s = (s or "").replace("ي", "ی").replace("ك", "ک")
    s = re.sub(r"[ \t]+", " ", s).strip()
    s = re.sub(rf"(?<![{PER}])(ن?می) (?=[{PER}])", rf"\1{ZW}", s)            # می‌کند
    s = re.sub(rf"(?<![{PER}])(بی) (?=[{PER}]{{2,}})", rf"\1{ZW}", s)          # بی‌نقص
    s = re.sub(rf"(?<=[{PER}]) (ها|های|هایی|هایش|هایت|هایم|هایمان|هایتان|هایشان)(?![{PER}])",
               rf"{ZW}\1", s)                                                   # هزینه‌هایش
    s = re.sub(rf"(?<=ه) (ام|ات|اش|ایم|اید|اند)(?![{PER}])", rf"{ZW}\1", s)     # داشته‌اند
    s = re.sub(rf"(?<=[{PER}]) (تر|ترین)(?![{PER}])", rf"{ZW}\1", s)           # بزرگ‌تر
    s = re.sub(rf"(?<=[{PER}])\?", "؟", s)
    s = re.sub(rf"(?<=[{PER}]),", "،", s)
    s = re.sub(rf"(?<=[{PER}]);", "؛", s)
    s = re.sub(r"\s+([،؛؟!:.])", r"\1", s)
    s = re.sub(rf"([،؛؟!:])(?=[{PER}])", r"\1 ", s)
    return s.translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))


def clean_display(s):
    """Subtitle text: no dangling comma/colon/period at the end."""
    return re.sub(r"[\s،,؛;:.\-–—]+$", "", strip_marks(s)).strip()


def parse(text):
    hook, tag, scenes = None, None, []
    for line in text.splitlines():
        line = fix_persian(line.strip())
        if not line:
            continue
        if line.startswith("#") and hook is None:
            hook = line.lstrip("#").strip()
            if "|" in hook:
                hook, tag = [x.strip() for x in hook.split("|", 1)]
            continue
        title, body = "", line
        if "::" in line:
            title, body = [x.strip() for x in line.split("::", 1)]
        scenes.append({"title": title, "text": body})
    if hook is None:
        hook = re.split(r"[.؟?!]", scenes[0]["text"])[0].strip() if scenes else ""
    return hook, tag, scenes


def split_chunks(text, max_chars=MAX_CHARS):
    out = []
    L = lambda x: len(strip_marks(x))
    for s in re.split(r"(?<=[\.؟\?!…؛])\s+", text.strip()):
        s = s.strip()
        if not s:
            continue
        if L(s) <= max_chars:
            out.append(s)
            continue
        cur = ""
        for p in re.split(r"(?<=[،,:])\s+", s):
            if cur and L(cur) + 1 + L(p) > max_chars:
                out.append(cur)
                cur = p
            else:
                cur = (cur + " " + p).strip()
        if cur:
            out.append(cur)
    final = []
    for p in out:
        while L(p) > max_chars * 1.5:
            cut = p.rfind(" ", 0, max_chars)
            cut = cut if cut > 15 else max_chars
            final.append(p[:cut].strip())
            p = p[cut:].strip()
        final.append(p)

    merged = []
    for part in final:
        part = part.strip()
        if not part:
            continue
        meaningful = re.sub(r"[^\w]", "", part, flags=re.UNICODE)
        if not meaningful:
            if merged:
                merged[-1] += part
            elif final:
                merged.append(part)
            continue
        if len(meaningful) <= 1 and merged:
            merged[-1] = (merged[-1] + " " + part).strip()
        else:
            merged.append(part)
    if len(merged) > 1:
        last_meaningful = re.sub(r"[^\w]", "", merged[-1], flags=re.UNICODE)
        if len(last_meaningful) <= 1:
            merged[-2] = (merged[-2] + " " + merged[-1]).strip()
            merged.pop()
    while len(merged) > 1 and not re.sub(r"[^\w]", "", merged[0], flags=re.UNICODE):
        merged[1] = (merged[0] + merged[1]).strip()
        merged.pop(0)
    return merged


# ------------------------------------------------------------------ Edge-TTS / audio
async def tts(text, out_wav, retries=4):
    """Generate speech robustly; Edge-TTS occasionally returns an empty stream."""
    text = (text or "").strip()
    if not text:
        raise ValueError("TTS received empty text.")
    out_wav = Path(out_wav)
    last_error = None
    for attempt in range(retries):
        try:
            out_wav.unlink(missing_ok=True)
            communicate = edge_tts.Communicate(text, VOICE, rate=RATE)
            await asyncio.wait_for(communicate.save(str(out_wav)), timeout=90)
            if not out_wav.exists() or out_wav.stat().st_size < 1024:
                raise RuntimeError("Edge-TTS returned an empty or incomplete audio file.")
            return
        except Exception as exc:
            last_error = exc
            out_wav.unlink(missing_ok=True)
            if attempt + 1 >= retries:
                break
            delay = min(2 ** attempt, 12)
            print(f"[TTS] Attempt {attempt + 1}/{retries} failed: {type(exc).__name__}: {exc}. "
                  f"Retrying in {delay}s...", flush=True)
            await asyncio.sleep(delay)
    raise RuntimeError(f"Edge-TTS failed after {retries} attempts for text: {text[:100]!r}. "
                       f"Last error: {type(last_error).__name__}: {last_error}") from last_error


def run(cmd):
    try:
        subprocess.run(cmd, check=True, capture_output=True)
    except subprocess.CalledProcessError as e:
        tail = (e.stderr or b"").decode("utf-8", "replace")[-1500:]
        raise RuntimeError(f"Command failed: {' '.join(map(str, cmd[:6]))} ...\n{tail}") from e


def duration(path):
    r = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration",
                        "-of", "default=nw=1:nk=1", str(path)],
                       capture_output=True, text=True, check=True)
    return float(r.stdout.strip())


TRIM = ("silenceremove=start_periods=1:start_threshold=-50dB:start_silence=0.03,areverse,"
        "silenceremove=start_periods=1:start_threshold=-50dB:start_silence=0.06,areverse")


def to_wav(src, dst, pad):
    """Trim TTS leading/trailing silence, then add our own punctuation-aware pause."""
    run(["ffmpeg", "-y", "-i", str(src), "-ar", "44100", "-ac", "2",
         "-af", f"{TRIM},apad=pad_dur={pad:.3f}", str(dst)])


def silence_wav(dst, seconds):
    run(["ffmpeg", "-y", "-f", "lavfi", "-i", "anullsrc=r=44100:cl=stereo",
         "-t", f"{seconds:.3f}", str(dst)])


def concat_wavs(paths, dst, d):
    lst = d / (dst.stem + "_list.txt")
    lst.write_text("".join(f"file '{p}'\n" for p in paths), encoding="utf-8")
    run(["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", str(lst), "-c", "copy", str(dst)])


def tts_safe_text(text):
    """Remove pictographs/emoji and ZWNJ before TTS (Edge-TTS may reject emoji)."""
    kept = [c for c in (text or "") if unicodedata.category(c)[0] in {"L", "N", "M", "P", "Z"}]
    return re.sub(r"\s+", " ", "".join(kept)).strip()


def chunk_pause(chunk, last, final_pause):
    if last:
        return final_pause
    end = strip_marks(chunk).rstrip()[-1:]
    if end in ".؟?!…":
        return PAUSE_SENT
    if end in "،,؛;:":
        return PAUSE_CLAUSE
    return PAUSE_CONT


async def build_scene_audio(idx, chunks, d, min_total=0.0, final_pause=SCENE_PAUSE, lead=0.0):
    wavs, timing, t = [], [], 0.0
    if lead > 0:
        lead_wav = d / f"a{idx:02d}_lead.wav"
        silence_wav(lead_wav, lead)
        wavs.append(lead_wav)
        t += lead
    for j, ch in enumerate(chunks):
        raw_audio = d / f"a{idx:02d}_{j:02d}_raw.wav"
        wav = d / f"a{idx:02d}_{j:02d}.wav"
        pause = chunk_pause(ch, j == len(chunks) - 1, final_pause)
        spoken = tts_safe_text(ch)
        if spoken:
            await tts(spoken, raw_audio)
            to_wav(raw_audio, wav, pause)
        else:
            silence_wav(wav, pause + 0.6)   # emoji-only chunk: shown, not spoken
        dur = duration(wav)
        timing.append((ch, t, t + dur))
        wavs.append(wav)
        t += dur
    if t < min_total:
        extra = d / f"a{idx:02d}_extra.wav"
        silence_wav(extra, min_total - t)
        wavs.append(extra)
        t = min_total
    scene_wav = d / f"scene{idx:02d}.wav"
    concat_wavs(wavs, scene_wav, d)
    return scene_wav, timing, duration(scene_wav)


